test('S3 fixture: object round trips and reserved part headers keep the service available',async t=>{
  const {createRequire}=await import('node:module'),{spawn}=await import('node:child_process'),{once}=await import('node:events');
  const {mkdtemp,rm}=await import('node:fs/promises'),{tmpdir}=await import('node:os'),{join}=await import('node:path');
  const fixture=createRequire(new URL('../.github/s3-fixture/package.json',import.meta.url)).resolve('@20minutes/s3rver');
  const directory=await mkdtemp(join(tmpdir(),'bane-storage-'));
  const child=spawn(process.execPath,['-e',`const S3rver=require(${JSON.stringify(fixture)});new S3rver({address:'127.0.0.1',port:0,directory:process.argv[1],vhostBuckets:false,allowMismatchedSignatures:true,silent:true,configureBuckets:[{name:'fixture'}]}).run().then(address=>process.send({port:address.port}));`,directory],{stdio:['ignore','ignore','pipe','ipc']});
  let log='';child.stderr!.on('data',chunk=>{log=(log+String(chunk)).slice(-4000);});
  t.after(async()=>{if(child.exitCode===null&&child.signalCode===null){child.kill();await once(child,'exit');}await rm(directory,{recursive:true,force:true});});
  const [{port}]=await once(child,'message',{signal:AbortSignal.timeout(5000)});
  const {S3Client,PutObjectCommand,GetObjectCommand,CopyObjectCommand,ListObjectsV2Command,DeleteObjectCommand}=await import('@aws-sdk/client-s3');
  const endpoint=`http://127.0.0.1:${port}`,client=new S3Client({endpoint,region:'us-east-1',forcePathStyle:true,credentials:{accessKeyId:'S3RVER',secretAccessKey:'S3RVER'}});
  t.after(()=>client.destroy());
  const key='workspaces/fixture/att/attachment_fixture',body='synthetic object bytes';
  await client.send(new PutObjectCommand({Bucket:'fixture',Key:key,Body:body,ContentType:'text/plain'}));
  assert.equal(await (await client.send(new GetObjectCommand({Bucket:'fixture',Key:key}))).Body!.transformToString(),body);
  await client.send(new CopyObjectCommand({Bucket:'fixture',Key:'copy.txt',CopySource:`fixture/${key}`}));
  const listing=await client.send(new ListObjectsV2Command({Bucket:'fixture'}));
  assert.deepEqual(listing.Contents!.map(item=>item.Key).sort(),['copy.txt',key]);
  for(const header of ['constructor: value','__proto__: value']){
    const response=await fetch(`${endpoint}/fixture`,{method:'POST',headers:{'content-type':'multipart/form-data; boundary=fixture'},body:`--fixture\r\n${header}\r\nContent-Disposition: form-data; name="file"\r\n\r\nfixture\r\n--fixture--\r\n`,signal:AbortSignal.timeout(5000)});
    assert.equal(response.status,400,log);await response.body?.cancel();
    assert.equal(child.exitCode,null,log);
  }
  assert.equal(await (await client.send(new GetObjectCommand({Bucket:'fixture',Key:'copy.txt'}))).Body!.transformToString(),body);
  for(const Key of [key,'copy.txt'])await client.send(new DeleteObjectCommand({Bucket:'fixture',Key}));
  assert.equal((await client.send(new ListObjectsV2Command({Bucket:'fixture'}))).KeyCount,0);
});
// PR #175 review M1 and M2: what a UI note keeps of the page's rendered text (app/src/lib/capture-text.ts). The
// screenshot's clone passes its text nodes, in order and split by block, through maskRuns.
test('UI notes capture text: an address split across inline elements is masked in every node it spans; credentials are removed', async () => {
  const { maskRuns, maskText, redactSecrets } = await import('../app/src/lib/capture-text.js');
  const hex = (n: number) => Array.from({ length: n }, (_, i) => '0123456789abcdef'[(i * 7 + 3) % 16]).join('');
  const random = 'Zx9Qw2Lp7Rt4Vb8Nm3Kc6Hj1Fg5Ds0Ae';
  // The reviewer's campaign-editor DOM: <p><a href="mailto:…"><strong>alice</strong>@example.net</a></p><p>Plain address: bob@example.net</p>.
  const rendered = maskRuns(['alice', '@example.net', '\n', 'Plain address: ', 'bob@example.net']);
  assert.deepEqual(rendered, ['al•••', '••••••••••••', '\n', 'Plain address: ', 'bo•••••••••••••']);
  assert.ok(!/alice|example\.net|bob@/.test(rendered.join('')));
  // Split three ways, inside a sentence; lengths are kept so the layout doesn't move.
  const three = ['Reply to ', 'ma', 'ry', '@north', 'wind.example', ' today'];
  const out = maskRuns(three);
  assert.deepEqual(out.map(t => t.length), three.map(t => t.length));
  assert.equal(out.join(''), 'Reply to ma•••••••••••••••••••• today');
  // Text in different blocks is never joined: a name in one cell stays readable beside an address in the next.
  assert.deepEqual(maskRuns(['Dana Rivera', '\n', 'dana@northwind.example']), ['Dana Rivera', '\n', 'da••••••••••••••••••••']);
  // A secret split across nodes is dotted out whole; resource IDs, class names and prose stay.
  const key = `bane_${hex(64)}`;
  assert.deepEqual(maskRuns(['Key: ', key.slice(0, 20), key.slice(20)]), ['Key: ', '•'.repeat(20), '•'.repeat(key.length - 20)]);
  const kept = [`cmp_${hex(32)}`, 'ui-table__clickable private-address__value', 'Section title sits 4px closer', 'abc123def456'];
  for (const text of kept) { assert.equal(redactSecrets(text), text); assert.deepEqual(maskRuns([text]), [text]); }
  const secrets = [key, `nm_${hex(64)}`, `nm_mbx_${hex(64)}`, `nm_notes_${hex(64)}`, `nm_agent_${random}.${random}`, `bane_notes_${hex(64)}`, `bane_agent_${random}.${random}`, `whsec_${random}`, `sk_live_${random}`, `rk_${random}`, `cus_${random.slice(0, 16)}`,
    Array.from({ length: 8 }, () => 'a1b2').join('-'), `eyJhbGciOiJIUzI1NiJ9.${random}.${random}`, 'AKIAIOSFODNN7EXAMPLE', `Bearer ${random}`, random, hex(40)];
  for (const secret of secrets) {
    assert.equal(redactSecrets(`before ${secret} after`).includes(secret), false, secret);
    assert.match(redactSecrets(`before ${secret} after`), /^before .*\[secret\].* after$/, secret);
    assert.ok(!maskRuns([`x ${secret} y`])[0]!.includes(secret.slice(-12)), secret);
  }
  assert.equal(maskText(`Sent to ada@example.net with ${key}`), 'Sent to ad••• with [secret]');
  // Recheck M2: invisible characters (default-ignorable and format) inside an address, as the campaign editor's code
  // block keeps them (<pre><code>carol\uFEFF@example.net</code></pre>). Every visible character after the first two is
  // dotted, the invisible ones stay where they are, and every node keeps its length.
  const invisible = ['\uFEFF', '\u200B', '\u200C', '\u200D', '\u2060', '\u00AD', '\u180E', '\u034F', '\u2063', '\u202E', '\u{E0001}', '\u3164'];
  for (const mark of invisible) {
    const name = `U+${mark.codePointAt(0)!.toString(16).toUpperCase()}`;
    for (const nodes of [[`carol${mark}@example.net`], ['carol', mark, '@example.net'], [`c${mark}arol@exa${mark}mple.net`], ['<', 'carol', `${mark}@exam`, 'ple.net', '>']]) {
      const out = maskRuns(nodes), visible = out.join('').replace(/[\p{Default_Ignorable_Code_Point}\p{Cf}]/gu, '');
      assert.deepEqual(out.map(t => t.length), nodes.map(t => t.length), name);
      assert.ok(!/arol|example|\.net/.test(visible) && /ca|<c/.test(visible), `${name} ${JSON.stringify(nodes)} → ${JSON.stringify(out)}`);
    }
    assert.equal(maskText(`Reply to carol${mark}@example.net`), 'Reply to ca•••', name);
    assert.equal(redactSecrets(`key bane_${mark}${hex(64)}`), 'key [secret]', name);
  }
});
// PR #144 review: a contact property is free text. Every run of non-space characters with an @ in it is masked whole,
// with any quoted string or comment it touches (app/src/lib/private-address.ts addressParts, components/AddressText.tsx).
test('dashboard addresses in free text: every run holding an @ is masked whole, with the quoted string or comment it touches', async () => {
  const { addressParts, maskedParts } = await import('../app/src/lib/private-address.js');
  const shown = (text: string) => addressParts(text).map(part => part.address ? `[${part.text}]` : part.text).join('');
  const cases: [string, string][] = [
    // Round 3: a comment before the @, and a local part no parser reads.
    ['bob(comment)@example.net', '[bob(comment)@example.net]'],
    ['Reach bob(my work comment)@example.net now', 'Reach [bob(my work comment)@example.net] now'],
    ['bob\\local@example.net', '[bob\\local@example.net]'],
    // Earlier rounds.
    ['Reach "mary smith"@example.net now', 'Reach ["mary smith"@example.net] now'],
    ['Reach "a@b \\" c"@example.net', 'Reach ["a@b \\" c"@example.net]'],
    ['Reach person@例子.公司 now', 'Reach [person@例子.公司] now'],
    ['first/last@example.net', '[first/last@example.net]'],
    ["o'connor@example.net", "[o'connor@example.net]"],
    ['dörte@münchen.example', '[dörte@münchen.example]'],
    // Over-masking is fine: the punctuation a run carries goes with it.
    ['Reply to second-person@example.net.', 'Reply to [second-person@example.net.]'],
    ['mailto:bob@example.net, <ada@example.net> (cc lin@example.net)', '[mailto:bob@example.net,] [<ada@example.net>] [(cc lin@example.net)]'],
    ['bob@example.net(Bob Smith) after', '[bob@example.net(Bob Smith)] after'],
    ['"mary smith"@x.example" tail', '["mary smith"@x.example"] tail'],
    ['"a@b.example y"@c.example tail', '["a@b.example y"@c.example] tail'],
    ['cut off: bob@', 'cut off: [bob@]'],
    // No mailbox in the run: handles, domains and catch-all patterns stay readable.
    ['@team ping *@bane.mx bane.mx', '@team ping *@bane.mx bane.mx'],
    ['plain prose, no address', 'plain prose, no address'],
  ];
  for (const [text, expected] of cases) {
    assert.equal(shown(text), expected, text);
    // Every readable piece is free of any @ that belongs to a mailbox; the pieces join back to the text.
    assert.equal(addressParts(text).map(part => part.text).join(''), text);
    for (const part of addressParts(text)) if (part.address) assert.ok(maskedParts(part.text), part.text);
  }
  // Fast on long text whatever it holds.
  const started = performance.now();
  addressParts('x@'.repeat(100_000) + ' ' + '"('.repeat(50_000) + '@'); addressParts('a "b" (c) d@e '.repeat(5_000));
  assert.ok(performance.now() - started < 1000, 'long text is split quickly');
});
